INSERT INTO batch_execution_log (
    job_name, job_group, started_at, status,
    records_processed, records_failed, retry_count,
    triggered_by, operator_id
) VALUES (
    #{jobName}, #{jobGroup}, #{startedAt}, #{status},
    COALESCE(#{recordsProcessed},0), COALESCE(#{recordsFailed},0),
    COALESCE(#{retryCount},0),
    COALESCE(#{triggeredBy},'SCHEDULE'), #{operatorId}
)

