SELECT * FROM batch_execution_log
WHERE job_group = #{jobGroup}

    AND started_at >= #{from}


    AND started_at < #{to}

ORDER BY started_at DESC
LIMIT 200

SELECT * FROM batch_execution_log

    AND job_group = #{p.jobGroup}
    AND status    = #{p.status}
    AND started_at >= #{p.from}
    AND started_at <  #{p.to}

ORDER BY started_at DESC
LIMIT #{p.size} OFFSET #{p.offset}

SELECT COUNT(*) FROM batch_execution_log

    AND job_group = #{p.jobGroup}
    AND status    = #{p.status}
    AND started_at >= #{p.from}
    AND started_at <  #{p.to}
